import{_ as e,o as a,c as l,a2 as r}from"./chunks/framework.ClgMjOt7.js";const f=JSON.parse('{"title":"作品を見る (イラスト・マンガ・小説)","description":"アプリの画面構成、ボトムナビゲーション、各メディアビューアの使い方","frontmatter":{"title":"作品を見る (イラスト・マンガ・小説)","description":"アプリの画面構成、ボトムナビゲーション、各メディアビューアの使い方"},"headers":[],"relativePath":"user/browse.md","filePath":"user/browse.md","lastUpdated":1789105872000}'),o={name:"user/browse.md"};function n(d,t,s,i,h,c){return a(),l("div",null,[...t[0]||(t[0]=[r('<h1 id="作品を見る-イラスト・マンガ・小説" tabindex="-1">作品を見る (イラスト・マンガ・小説) <a class="header-anchor" href="#作品を見る-イラスト・マンガ・小説" aria-label="Permalink to &quot;作品を見る (イラスト・マンガ・小説)&quot;">​</a></h1><p>画面下部のボトムナビゲーションバーおよび各ボタンから、様々なジャンルの作品へアクセスできます。</p><hr><h2 id="ナビゲーションと画面構成" tabindex="-1">ナビゲーションと画面構成 <a class="header-anchor" href="#ナビゲーションと画面構成" aria-label="Permalink to &quot;ナビゲーションと画面構成&quot;">​</a></h2><h3 id="_1-下部ナビゲーションバー-5-つのメインタブ" tabindex="-1">1. 下部ナビゲーションバー (5 つのメインタブ) <a class="header-anchor" href="#_1-下部ナビゲーションバー-5-つのメインタブ" aria-label="Permalink to &quot;1. 下部ナビゲーションバー (5 つのメインタブ)&quot;">​</a></h3><p>アプリ画面下部には、メインとなる 5 つのタブが配置されています。</p><table tabindex="0"><thead><tr><th style="text-align:left;">タブ</th><th style="text-align:left;">アイコン</th><th style="text-align:left;">説明</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>ホーム</strong></td><td style="text-align:left;"><code>Home</code></td><td style="text-align:left;">「おすすめ」および「フォロー中」の 2 タブで最新投稿をチェックできます</td></tr><tr><td style="text-align:left;"><strong>検索 / ショート</strong></td><td style="text-align:left;"><code>Search</code> / <code>ShortsFeed</code></td><td style="text-align:left;">キーワード検索画面。ショートフィード有効時は縦スワイプ観賞フィードになります</td></tr><tr><td style="text-align:left;"><strong>ブックマーク</strong></td><td style="text-align:left;"><code>Bookmarks</code></td><td style="text-align:left;">自身が保存した公開 / 非公開ブックマーク作品の一覧</td></tr><tr><td style="text-align:left;"><strong>ランキング</strong></td><td style="text-align:left;"><code>Ranking</code></td><td style="text-align:left;">デイリー、ウィークリー、マンスリー、R-18 各種の人気作品一覧</td></tr><tr><td style="text-align:left;"><strong>その他</strong></td><td style="text-align:left;"><code>More</code></td><td style="text-align:left;">設定、閲覧履歴、ダウンロードキュー、オフラインライブラリ、通知へのハブ</td></tr></tbody></table><hr><h3 id="_2-小説画面の開き方-novelscreen" tabindex="-1">2. 小説画面の開き方 (<code>NovelScreen</code>) <a class="header-anchor" href="#_2-小説画面の開き方-novelscreen" aria-label="Permalink to &quot;2. 小説画面の開き方 (`NovelScreen`)&quot;">​</a></h3><p>小説作品（一覧・ランキング・連載・本文リーダー）は、<strong>ホーム画面などの右上にある「小説アイコン（ボタン）」</strong> をタップして呼び出します。</p><hr><h2 id="各メディア別ビューアの機能" tabindex="-1">各メディア別ビューアの機能 <a class="header-anchor" href="#各メディア別ビューアの機能" aria-label="Permalink to &quot;各メディア別ビューアの機能&quot;">​</a></h2><h3 id="_1-イラスト・マンガビューア" tabindex="-1">1. イラスト・マンガビューア <a class="header-anchor" href="#_1-イラスト・マンガビューア" aria-label="Permalink to &quot;1. イラスト・マンガビューア&quot;">​</a></h3><ul><li><strong>拡大表示</strong>: ピンチイン / ピンチアウト（二本指操作）またはダブルタップで画像を拡大・縮小。</li><li><strong>マンガ表示モード</strong>: 連続スライド表示、単ページ切り替え、見開き表示。</li><li><strong>画質制御</strong>: データ通信量に合わせてサムネイル解像度、詳細表示画質、原寸表示を個別に設定可能。</li></ul><h3 id="_2-うごイラ-動くイラスト" tabindex="-1">2. うごイラ (動くイラスト) <a class="header-anchor" href="#_2-うごイラ-動くイラスト" aria-label="Permalink to &quot;2. うごイラ (動くイラスト)&quot;">​</a></h3><ul><li>連続フレーム画像を自動解凍し、スムーズにアニメーション再生。</li><li>画面タップで再生 / 一時停止、コマ送り操作が可能。</li></ul><h3 id="_3-小説リーダー" tabindex="-1">3. 小説リーダー <a class="header-anchor" href="#_3-小説リーダー" aria-label="Permalink to &quot;3. 小説リーダー&quot;">​</a></h3><ul><li><strong>縦書き表示</strong>: 和文書籍に最適な「縦書き表示」と右開きページ推移をサポート。</li><li><strong>背景と文字のカスタマイズ</strong>: 文字サイズ、行間、背景色（ホワイト / セピア / ダーク）を変更可能。</li><li><strong>挿絵</strong>: 本文中の挿絵タグを自動検出してインライン表示およびタップ拡大表示。</li></ul>',18)])])}const _=e(o,[["render",n]]);export{f as __pageData,_ as default};
